#' Compile EMA Output
#'
#' Function to create output dataframes from a list of EMA results
#'
#' @param resultList list - list of results generated by the emafit() function. 
#' Each list item is a list of results from emafit(). 
#'
#' @return A list containing outputs combined for all analyses in the input list:
#'  1. Dataframe of estimated moments and other EMA analysis info
#'  2. Dataframe with fitted frequency curve
#'  3. Dataframe of MGBT p values
#'  4. List of quantile curves (used for plotting)
#'
#' @keywords internal
#'
EMAout <- function(resultList){
  
  info <- data.frame() #Fitted moments, MGBT results, and other output
  qnt <- data.frame() #Quantile output
  MGBTpvals <- data.frame() #MGBT p values
  
  #Also need quantile curves as a list to feed to plot function
  qntList <- list()
  
  
  for(n in 1:length(resultList)){
    
    siteNum <- names(resultList)[n]
    
    siteEXP <- resultList[[n]][[1]]
    siteQnt <- resultList[[n]][[2]]
    siteMGBT <- resultList[[n]][[4]]
    
    siteEXP$site_no <- siteNum
    #siteEXP$station_nm <- siteInfo$station_nm[siteInfo$site_no == siteNum]
    siteEXP <- siteEXP[, c(ncol(siteEXP), 1:(ncol(siteEXP)-1))]
    
    siteQnt$site_no <- siteNum
    siteQnt <- siteQnt[, c(ncol(siteQnt), 1:(ncol(siteQnt)-1))]
    
    #Compute K values needed for WREG
    siteQnt$K_Value <- k_17b(siteQnt$EXC_Prob, siteEXP$Skew)
    
    
    siteMGBT$site_no <- siteNum
    siteMGBT <- siteMGBT[, c(ncol(siteMGBT), 1:(ncol(siteMGBT)-1))]
    
    
    # #Remove data for quantiles less than PILF threshold
    # if(!is.na(siteEXP$PILF_Thresh)){
    #   if(nrow(siteQnt[siteQnt$Estimate < siteEXP$PILF_Thresh, ]) > 0){
    #     siteQnt[siteQnt$Estimate < siteEXP$PILF_Thresh, c("Estimate", "Variance", "Conf_Low", "Conf_Up", "K_Value")] <- NA
    #   }
    # }
    
    info <- rbind(info, siteEXP)
    qnt <- rbind(qnt, siteQnt)
    MGBTpvals <- rbind(MGBTpvals, siteMGBT)
    
    qntList <- append(qntList, list(as.data.frame(siteQnt)))

    
  }
  
  names(qntList) <- names(resultList)
  
  #Round moments to three decimal places
  info[, c('Mean',
           'StandDev',
           'Skew',
           'AtSiteMean',
           'AtSiteStandDev',
           'AtSiteSkew',
           'AtSiteMSEG',
           'AtSiteMSEG_GagedOnly',
           'RegMSEG',
           'WeightCo', 
           'RunTime')] <- round(info[, c('Mean',
                                         'StandDev',
                                         'Skew',
                                         'AtSiteMean',
                                         'AtSiteStandDev',
                                         'AtSiteSkew',
                                         'AtSiteMSEG',
                                         'AtSiteMSEG_GagedOnly', 
                                         'RegMSEG',
                                         'WeightCo', 
                                         'RunTime')],
                                             4)
  

  #Round PILFs to two decimal places
  info$PILF_Thresh <- round(info$PILF_Thresh, 2)
  
  #Round quantile outputs to 4 significant figures or 1 decimal place, 
  #whichever is larger
  qnt$Estimate <- round(signif(qnt$Estimate, 4), 1)
  qnt$Conf_Low <- round(signif(qnt$Conf_Low, 4), 1)
  qnt$Conf_Up <- round(signif(qnt$Conf_Up, 4), 1)
  qnt$nu <- qnt$nu
  
  #Round variance to 4 decimal places
  qnt$Variance <- round(qnt$Variance, 4)
  
  #Round K to 4 significant figures or 4 decimal places
  qnt$K_Value <- round(signif(qnt$K_Value, 4), 4)
  
  
  MGBTpvals$peak_va <- round(MGBTpvals$peak_va, 3)
  MGBTpvals$p_value <- round(MGBTpvals$p_value, 4)
  
  
  return(list(info, qnt, MGBTpvals, qntList))
  
}






#' Compile Emperical Plotting Position Output
#'
#' Function to create output dataframe from a list of EMA and EMP results
#'
#' @param resultList list - list of results generated by the emafit() function. 
#' Each list item is a list of results from emafit(). 
#' @param empResults list - list of results generated by the plotPosHS() function. 
#' Each list item is a list of results from plotPosHS(). 
#'
#' @return A list containing outputs combined for all analyses in the input list:
#'  1. List of dataframes of empirical plotting positions and EMA data representation
#'  2. List of dataframes of EMA data representation for each analysis (used for plotting)
#'
#' @keywords internal
#'
EMPout <- function(resultList, empResults){
  
  empList <- list() #Empirical plotting positions as list for use with plot function
  EMArepList <- list() #EMA representations for plots
  
  for(n in 1:length(empResults)){
    siteNum <- names(empResults)[n]
    
    #Append site EMA representation to site plotting positions
    siteEMArep <- resultList[[n]][[3]]
    
    empResults[[n]] <- cbind(empResults[[n]], siteEMArep)
    
    siteEMP <- empResults[[n]]
    
    siteEMP$site_no <- siteNum
    siteEMP <- siteEMP[, c(ncol(siteEMP), 1:(ncol(siteEMP)-1))]
    
    #Copy site EMA representation to separate data frame for later plotting
    siteEMArep <- siteEMP[, c("peak_WY", "peak_va", "historic",   "ql_ema",  "qu_ema",   "tl_ema", "tu_ema")]
    
    siteEMP$plot_pos <- round(siteEMP$plot_pos, 4)
    siteEMP$peak_va <- signif(siteEMP$peak_va, digits = 5) #Clean up roundoff
    
    siteEMP$peak_va[siteEMP$ql != siteEMP$qu] <- NA #Set interval peaks to NA
    
    #Remove _ema from column names for supplying to plot function
    colnames(siteEMArep) <- gsub("_ema", "", colnames(siteEMArep))
    
    empList <- append(empList, list(as.data.frame(siteEMP)))
    EMArepList <- append(EMArepList, list(as.data.frame(siteEMArep)))
  }
  
  names(empList) <- names(EMArepList) <- names(empResults)
  
  return(list(empList, EMArepList))
  
}


#' Run Trend Test
#'
#' Perform the Mann-Kendall test based on the input data
#' using the 'trends' package.  
#' 
#' @param qt_df the QT dataframe 
#' 
#' @details
#' Only uncensored data values are used in the trend test and historical
#' data values are excluded. 
#' 
#'
#' @keywords internal
#' 
#' @importFrom trend mk.test
#' @importFrom trend sens.slope
#'
#' 
trend_test <- function(qt_df){
  
  df <- qt_df[qt_df$ql == qt_df$qu,] #Test only exactly known peaks
  df <- df[df$dtype == 0,] #Exclude historic peaks
  
  
  mk_res <- trend::mk.test(df$ql)
  p_value <- mk_res[[2]]
  n_peaks <- mk_res[[5]]
  tau <- mk_res[[6]][3]
  
  
  
  
  #Compute Sen slope
  slope_res <- trend::sens.slope(df$ql)
  median_slope <- slope_res[[1]]
  
  df_res <- data.frame(site_no = attributes(qt_df)$site_no,
                       tau = round(tau, 3),
                       p_value = round(p_value, 3),
                       median_slope = round(median_slope, 3),
                       n_peaks = n_peaks,
                       row.names = NULL)
  
  return(df_res)
  
}


#' Assemble plot text
#'
#' Function to create analysis information text for flood frequency curve plot
#'
#' @param infoFrame data frame - data frame of site information produced
#'                  by EMAout()
#'
#' @return Vector containing text strings for plots for each site in the
#'         analysis
#'
#' @keywords internal
#'
plotText <- function(infoFrame){
  
  t <- format(Sys.time(), "%m/%d/%Y %H:%M")
  
  #Make nice text for low-outlier information
  infoFrame$PILF_Method_text <- infoFrame$PILF_Method
  infoFrame$PILF_Method_text[infoFrame$PILF_Method == "MGBT"] <- "Multiple Grubbs-Beck"
  infoFrame$PILF_Method_text[infoFrame$PILF_Method == "FIXED"] <- paste0("PILF fixed at ", infoFrame$PILF_Thresh[infoFrame$PILF_Method == "FIXED"])
  
  txt <- paste0("ANALYSIS INFO \n", 
        "peakfq v ", packageVersion("peakfq"), " run ", t, "\n",
        round(infoFrame$Skew, 3), " = Skew (", infoFrame$SkewOption, " skew option) \n", 
        infoFrame$PILF_Method_text, "\n", 
        infoFrame$PILFs, " Peaks below PILF (low outlier) Threshold \n", 
        infoFrame$PILF_0s, " Zeroes not displayed")
  
  return(txt)
  
}



#' Create peakfq log file text
#'
#' Function to create log file text for peakfq
#'
#' @param inPSF inPSF character - path to specifications file for peakfq
#' @param specs data frame - first data frame in list returned by `readPSF()`
#' @param results_info data frame - data frame with EMA analysis info 
#' @param results_qnt data frame - data frame with EMA quantile results 
#' @param warnList list - list with text from warnings to be saved to log file
#' @param outFiles character - vector of output file paths
#' 
#' @return Character vector of text for log file. Each vector element is a row for the log file. 
#'
#' @keywords internal
#'
logText <- function(inPSF="", specs=NULL, results_info=NULL, results_qnt = NULL, warnList = list(), outFiles = c()){
  
  t <- format(Sys.time(), "%m/%d/%Y %H:%M")
  
  AEPs <- c(0.6667, 0.5000, 0.4292, 0.2000, 0.1000, 0.0400, 0.0200, 0.0100, 0.0050, 0.0020)
  
  header_text_1 <- c("   ANNUAL                                                 ")
  header_text_2 <- c("EXCEEDANCE            LOG VARIANCE   <- CONFIDENCE LIMITS- >") 
  
  
  if(is.data.frame(results_qnt)){
    results_qnt <- results_qnt[results_qnt$EXC_Prob %in% AEPs,]
    
    #Split into dataframes by site number
    qnt_list <- split(results_qnt , f = results_qnt$site_no)
    
    #Use function to create text table for each site
    qnt_text <-sapply(qnt_list, resultsText) 
    
    #Format confidence limits for table headers
    ConfInterval <- unique(results_qnt$Conf_Interval)
    ConfLow <- (1-ConfInterval)/2
    ConfUp <- 1- ConfLow
    
    header_text_3 <- paste0("PROBABILITY ESTIMATE     OF EST.    ", 
                            sprintf("%2.1f", ConfLow*100), "% LOWER   ",
                            sprintf("%2.1f", ConfUp*100), "% UPPER") 
    
  }
  
  
  if(is.data.frame(results_info)){
    site_name_num <- paste("  Station - ", results_info$site_no, results_info$station_nm)
    
    #header_text <- rep(header_text, length(site_name_num))
    
  }
  else{
    site_name_num <- ""
  }
  
  if(length(outFiles) == 5){
    outFiles <- paste(c("                    Log-Pearson Type III Fit Summary:", 
                        " Quantile Estimates, Variance, and Confidence Limits:", 
                        "Empirical Plotting Positions and Data Representation:", 
                        "                  Multiple Grubbs-Beck Test P-Values:", 
                        "                                  Trend Test Results:"), 
                      outFiles)
  }
  
  
  txt <- c("  Program peakfq           U. S. GEOLOGICAL SURVEY                        ",
           paste0("Version ", packageVersion("peakfq"), "       Annual peak flow frequency analysis      Run Date / Time"),
           paste0(format(packageDate("peakfq"), "%m/%d/%Y"), "                                                     ", t),
           "",
           "                         --- PROCESSING OPTIONS ---  ",
           "",
           "                      Input files used:",
                
           paste0("                         peaks (", attributes(specs)$peakFormat, ")  - ", attributes(specs)$peakFile),
           paste0("                        specifications - ", inPSF),
           paste0("                      Output directory - ", attributes(specs)$outFile),
                
           "  *** User responsible for assessment and interpretation of the following analysis ***",
           "",
           "",
           #Make warnings section conditional on having warnings
           "  ********  The following warnings occurred when running the analysis: ********",
           "",
           
           unlist(warnList),
           
           "",
           "  ********                        OUTPUT FILES                        ********",
           "",
           
           outFiles,
           
           "",
           "  ********                      SUMMARY RESULTS                       ********",
           "",
           
           c(rbind( site_name_num, header_text_1, header_text_2, header_text_3, qnt_text, "")), 
           
           "  ********                 OUTPUT FILE EXPLANATION                    ********",
           "",
           "basename_lp3.csv - Comma delimited file with estimated moments, PILF information, and other information used to fit the log-Pearson Type 3 distribution", 
           "    site_no - unique site identifier", 
           "    station_nm - site (station) name",
           "    BegYear - Beginning year of the analysis",
           "    EndYear - Ending year of the analysis",
           "    RecordLength - Number of years of data in the analysis. Does not include missing data years for which no information is available (lower perception threshold of infinity)",
           "    SkewOption - Analysis skew option - either 'Station', 'Weighted', or 'Generalized'",
           "    Mean - Mean (in log units) of data", 
           "    StandDev - Standard deviation (in log units) of data", 
           "    Skew - Skew of log-transformed data",
           "    AtSiteMean - Mean (in log units) of data, without regional skew",
           "    AtSiteStandDev - Standard deviation (in log units) of data, without regional skew",
           "    AtSiteSkew - Skew of log-transformed data, without regional skew",
           "    AtSiteMSEG - Mean Squared Error of the at-site skew coefficient",
           "    AtSiteMSEG_GagedOnly - Mean Squared Error of the at-site skew coefficient without censoring",
           "    RegSkew - Regional skew coefficient",
           "    RegMSEG - Mean Squared Error of the regional skew coefficient", 
           "    HistPeaks - Number of historical peaks in the analysis",
           "    MGBTPeaks - Number of peaks available for Multiple Grubbs-Beck low outlier test. Computed as number of exactly known (lower flow interval value equal to upper flow interval value) input peaks, excluding historic peaks, plus any not exactly known peaks with the upper flow interval value less than the smallest exactly known peak value.",
           "    PILF_Method - Potentially Influential Low Flow threshold method; either 'MGBT' or 'FIXED'",
           "    PILF_Thresh - Potentially Influential Low Flow threshold",
           "    PILFs - Number of values below the PILF threshold",
           "    PILF_0s - Number of zero values below the PILF threshold. Zero values are always counted as PILFs.",
           "    WeightOpt - Option for algorithm to computed weighted skew coefficient. Possible values are HWN (default; a generalization of the PeakFQ 7.4.1 algorithm using an optimized adjustment factor when censored data are present, results are identical to PeakFQ 7.4.1 when no censored data are present), INV (identical to PeakFQ 7.4.1 and earlier), and ERL (identical to HEC-SSP 2.3)",
           "    WeightCo - Censored data adjustment factor for computing weighted skew coefficient", 
           "    RunTime - Time to run analysis, in seconds", 
           "",
           "basename_qnt.csv - Comma delimited file with quantile estimates, variances, and confidence intervals",
           "    site_no - unique site identifier", 
           "    EXC_Prob - Annual exceedance probability",
           "    Estimate - Estimated discharge, in cubic feet per second", 
           "    Variance - Variance of estimate, in log units",
           "    Conf_Low - Lower confidence limit, in cubic feet per second",
           "    Conf_Up - Upper confidence limit, in cubic feet per second",
           "    K_Value - K value from Bulletin 17B Appendix 3",
           "    Conf_Interval - confidence interval. Default is 0.90 (90-percent confidence interval)", 
           "", 
           "basename_emp.csv - Comma delimited file with input data representation and empirical plotting positions ",
           "    site_no - unique site identifier",
           "    peak_WY - water year of peak flow",
           "    peak_va - peak flow value",
           "    plot_pos - plotting position of peak flow, computed using Hirsch-Stedinger plotting positions",
           "    ql - lower flow interval value, in cubic feet per second",
           "    qu - upper flow interval value, in cubic feet per second",
           "    tl - lower perception threshold, in cubic feet per second",
           "    tu - upper perception threshold, in cubic feet per second",
           "    historic - true or false indicator of whether or not data value is a historic peak",
           "    ql_ema - lower flow interval value used in Expected Moments Algorithm, in cubic feet per second. Will be identical to `ql` if no PILF values are identified.",
           "    qu_ema - upper flow interval value used in Expected Moments Algorithm, in cubic feet per second. Will be identical to `qu` if no PILF values are identified.",
           "    tl_ema - lower perception threshold used in Expected Moments Algorithm, in cubic feet per second.",
           "    tu_ema - upper perception threshold used in Expected Moments Algorithm, in cubic feet per second.",
           "",
           "basename_mgb.csv - Comma delimited file with MGBT p-values", 
           "    site_no - unique site identifier", 
           "    peak_va - peak flow value identified as a low outlier by the Multiple Grubbs-Beck Test. NA values indicate no low outliers were identified for the site.",
           "    p_value - p-value associated with peak flow value. NA values indicate no low outliers were identified for the site.", 
           "", 
           "basename_trd.csv - Comma delimited file with Mann-Kendall trend test results", 
           "    site_no - unique site identifier", 
           "    tau - Kendall's tau value", 
           "    p_value - p-value from Mann-Kendall test", 
           "    median_slope - Median slope from Mann-Kendall test", 
           "    n_peaks - number of peak values used in Mann-Kendall test"
           
           
                )
  
  return(txt)
  
}


#' Format Results Text
#'
#' Formats quantile estimate results as text for printing as a table in log file
#'
#' @param results_qnt data frame containing quantile results in the following columns EXC_Prob, Estimate, Variance, Conf_Low, and Conf_Up
#'
#' @return Character vector text for results table in log file. Each vector element is a row for the log file. 
#'
#' @keywords internal
#'
resultsText <- function(results_qnt){
  
  txt <- sprintf("%8.4f%12.1f%12.4f%14.1f%14.1f",
          results_qnt$EXC_Prob,
          results_qnt$Estimate,
          results_qnt$Variance,
          results_qnt$Conf_Low,
          results_qnt$Conf_Up)
  
  return(txt)
  
}


